    send_to_it: function(frm){
        //console.log( frm.get_docinfo().assignments);
        console.log(frm.doc.deployment_locations);
        var locationArr = frm.doc.deployment_locations.map(location => location.deployment_locations);
        console.log(locationArr);
        locationArr.forEach(location =>{
            frappe.call({
	            method: 'frappe.client.get_value',
	            args: {
	            'doctype': 'Deployment Location',
            	'filters': {'name': location},
	            'fieldname':['full_shipping_address', 'full_billing_address', 'customer_name','city_name','state_name','country_name','machines_at_location','total_lockers_at_location','number_of_kiosks','number_of_vaults']
            	},
                    callback: function(r){						
                       var shippingAddress = r.message.full_shipping_address;
                       var billingAddress = r.message.full_billing_address;
                       BuildDeployment(r);
                       console.log(location);
                       console.log(shippingAddress);
                       console.log(billingAddress);


	            }
            });
        });

        function  BuildDeployment(r)
        {
            projectName = buildSubject(r);

            frappe.db.insert({
                doctype: 'Project',
                project_type: 'Deployment',
                project_name: projectName,
                related_warehouse_request: frm.doc.name,
                related_deployment: frm.doc.related_project,
                issue_type: 'Desktop Support',
                case_reason: 'Desktop Support',
                case_sub_reason: 'Connectivity',
                connectivity_type: frm.doc.connectivity,
                connectivity_devices_quantity: frm.doc.connectivity_device_quantity,
                machine_name: frm.doc.machine_names,
                customer: frm.doc.account,
                deployment_owner: frm.doc.created_by

            }).then(doc => {
                console.log(doc);
        });
        }

        function buildSubject (r){
            var subject;

            if(r.messgae.country_name == 'United States'){
                subject = r.message.customer_name + ' - '+ r.message.city_name + ', '+ r.message.state_name + '('+r.message.machines_at_location +','+ r.message.total_lockers_at_location +','+r.message.number_of_vaults+','+r.message.number_of_kiosks;
            }else{
                subject = r.message.customer_name + ' - '+ r.message.city_name + ', '+ r.message.country_name + '('+r.message.machines_at_location +','+ r.message.total_lockers_at_location +','+r.message.number_of_vaults+','+r.message.number_of_kiosks;
            }
            return subject;

        }
