frappe.ui.form.on('Project', {
	onload(frm) {
		if(frm.doc.expected_start_date === undefined || frm.doc.expected_start_date > frm.doc.creation ){
		    frm.doc.expected_start_date = frm.doc.creation;
		    if(frm.doc.expedited_delivery === 1){
		        cur_frm.set_value("expected_end_date", frappe.datetime.add_days(frm.doc.expected_start_date, +56));
		        cur_frm.set_value("target_ship_date", frappe.datetime.add_days(frm.doc.expected_start_date, +42));

		    }else{
		        cur_frm.set_value("expected_end_date", frappe.datetime.add_days(frm.doc.expected_start_date, +70));
		        cur_frm.set_value("target_ship_date", frappe.datetime.add_days(frm.doc.expected_start_date, +56));
		    }

		}else{
		        if(frm.doc.expected_end_date === undefined || ((frm.doc.expected_end_date > frappe.datetime.add_days(frm.doc.expected_start_date, +70) && frm.doc.expedited_delivery === 0 ) || (frm.doc.expected_end_date > frappe.datetime.add_days(frm.doc.expected_start_date, + 56) && frm.doc.expedited_delivery === 1 ))){
		            if(frm.doc.expedited_delivery === 1){
